const message = $input.all()[0].json.message;
const text = message.text;
const telegramUser = message.from;

// Вспомогательная функция полной очистки строки от лишних пробелов
function cleanStr(str) {
  return (str || '').toString().trim().replace(/\s+/g, ' ');
}

// Нормализация времени: обрезаем пробелы и приводим "8:00" -> "08:00"
function cleanTime(t) {
  let cleaned = cleanStr(t);
  if (/^\d:\d{2}$/.test(cleaned)) {
    cleaned = '0' + cleaned;
  }
  return cleaned;
}

// Разбиваем ввод пользователя по запятым
const parts = text.split(',').map(s => cleanStr(s));
const route = parts[0] || '';
const date = parts[1] || '';
const time = parts[2] || '';

// Разбиваем маршрут по дефису
const routeParts = route.split('-').map(s => cleanStr(s));
const dep_name = routeParts[0] || '';
const arr_name = routeParts[1] || '';

// Разбиваем время по дефису
const timeParts = time.split('-').map(s => cleanStr(s));
const time_from = cleanTime(timeParts[0] || '');
const time_to = cleanTime(timeParts[1] || '');

return {
  json: {
    telegram_id: telegramUser.id,
    username: cleanStr(telegramUser.username),
    first_name: cleanStr(telegramUser.first_name),
    dep_name,
    arr_name,
    date,
    time_from,
    time_to
  }
};

const sqlResult = $('filter').first().json;
const inputData = $('Parse Telegram Input').first().json;

const MAX_LIMIT = 2;
let error = null;

function isValidTimeFormat(t) {
  return /^([01]\d|2[0-3]):([0-5]\d)$/.test(t || '');
}

function isValidDateFormat(d) {
  return /^\d{4}-\d{2}-\d{2}$/.test(d || '');
}

// 1. Проверка существования городов в базе
if (!sqlResult.dep_city_id) {
  error = `❌ Город отправления "${inputData.dep_name}" не найден в базе.`;
} else if (!sqlResult.arr_city_id) {
  error = `❌ Город прибытия "${inputData.arr_name}" не найден в базе.`;
}
// 2. Проверка на одинаковые города
else if (Number(sqlResult.dep_city_id) === Number(sqlResult.arr_city_id)) {
  error = '❌ Город отправления и прибытия не могут совпадать!';
}
// 3. Проверка лимита подписок
else if (Number(sqlResult.active_count || 0) >= MAX_LIMIT) {
  error = `⚠️ У тебя уже создано максимальное количество подписок (${MAX_LIMIT}). Удали старые, чтобы создать новую!`;
}
// 4. Проверка точного дубликата
else if (Number(sqlResult.duplicate_count || 0) > 0) {
  error = 'ℹ️ У тебя уже есть точно такая же активная подписка!';
}
// 5. Проверка формата даты и времени
else if (!isValidDateFormat(inputData.date)) {
  error = '❌ Некорректный формат даты! Используй формат ГГГГ-ММ-ДД (например, 2026-11-12).';
}
else if (!isValidTimeFormat(inputData.time_from) || !isValidTimeFormat(inputData.time_to)) {
  error = '❌ Некорректный формат времени! Используй ЧЧ:ММ (например, 07:00 или 18:30).';
}
// 6. Проверка интервала (время ОТ < ДО)
else if (inputData.time_from >= inputData.time_to) {
  error = '❌ Время "ДО" должно быть строго позже времени "ОТ"!';
}
// 7. Проверка даты (не в прошлом)
else {
  const selectedDate = new Date(inputData.date);
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  if (selectedDate < today) {
    error = '❌ Нельзя выбрать дату в прошлом!';
  }
}

return {
  json: {
    isValid: !error,
    errorMessage: error,
    user_id: sqlResult.user_id,
    dep_city_id: sqlResult.dep_city_id,
    dep_atlas_id: sqlResult.dep_atlas_id,
    arr_city_id: sqlResult.arr_city_id,
    arr_atlas_id: sqlResult.arr_atlas_id,
    dep_name: inputData.dep_name,
    arr_name: inputData.arr_name,
    date: inputData.date,
    time_from: inputData.time_from,
    time_to: inputData.time_to,
    telegram_id: inputData.telegram_id
  }
};

const response = $input.first().json;

const timeFrom = response.time_from || $('Parse Telegram Input').first()?.json?.time_from || '00:00';
const timeTo = response.time_to || $('Parse Telegram Input').first()?.json?.time_to || '23:59';

// 1. Если API вернет ошибку (нет такого маршрута или дата совсем не существует)
if (response.path && response.timestamp) {
  return [{
    json: {
      action: 'NOTIFY_DATE_NOT_OPEN',
      message: '📅 На эту дату продажи ещё не открыты или маршрут не существует.'
    }
  }];
}

const rawRides = response.rides || [];
const calendar = response.calendar || [];

// 2. Если календаря нет вовсе — дата закрыта
if (!calendar || !Array.isArray(calendar) || calendar.length === 0) {
  return [{
    json: {
      action: 'NOTIFY_DATE_NOT_OPEN',
      message: '📅 Продажа билетов на эту дату ещё не открыта.'
    }
  }];
}

// 3. Фильтруем рейсы, которые ПОПАДАЮТ в интервал пользователя и ИМЕЮТ места > 0
const availableRides = rawRides.filter(ride => {
  const rideTime = ride.departure.split('T')[1].slice(0, 5); // HH:mm
  return rideTime >= timeFrom && rideTime <= timeTo && (ride.freeSeats || 0) > 0;
});

// 4. ЕСЛИ ДОСТУПНЫХ МЕСТ НЕТ — ОТПРАВЛЯЕМ НА СОЗДАНИЕ ПОДПИСКИ (ADD_TO_TRACKING)
if (availableRides.length === 0) {
  return [{
    json: {
      action: 'ADD_TO_TRACKING',
      message: `😔 На промежуток с ${timeFrom} до ${timeTo} свободных мест нет. Поставили маршрут на отслеживание!`
    }
  }];
}

// 5. Если свободные места есть — сортируем по времени и отдаем первые 10
availableRides.sort((a, b) => new Date(a.departure) - new Date(b.departure));
const top10 = availableRides.slice(0, 10);

let messageText = `🚌 *Найдено рейсов: ${availableRides.length}*\n`;
if (availableRides.length > 10) {
  messageText += `_Показаны первые 10_\n`;
}
messageText += `\n`;

messageText += top10.map(r => {
  const depTime = r.departure.split('T')[1].slice(0, 5);
  const arrTime = r.arrival.split('T')[1].slice(0, 5);
  const currency = r.currency || 'BYN';

  return `⏰ *${depTime}* ➔ *${arrTime}*\n💰 *${r.price} ${currency}*  |  💺 Мест: *${r.freeSeats}*`;
}).join('\n\n');

return [{
  json: {
    action: 'SHOW_RIDES',
    count: availableRides.length,
    formattedText: messageText
  }
}];
